CustomField.description:
IF(RecordTypeId = $Label.SFOM_In_Person_Record_Type_Id, 
   AND(!Is_PWN_Approved__c,  ISBLANK(InvoiceId),
       !ISPICKVAL( Status , 'Draft'),!ISPICKVAL( Status , 'Expired'),
       !ISPICKVAL( Status , 'PA Rejected'),!ISPICKVAL( Status , 'Cancelled')
   ),

  if(RecordTypeId=$Label.SFOM_At_Home_Self_Record_Type_ID||RecordTypeId=  $Label.SFOM_OTC_Cleared_Record_Type_Id,
      !Is_PWN_Approved__c && !ISBLANK(PWN_ID__c) ,
  False)
) || RecordType.DeveloperName='GSS'
